API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Azure_API_Management, "Azure API Management", "Azure API Management / NGINX", "Provides dynamic path-based routing, WAF integration, and rate limiting.")
    Component(Authentication_SSO_Handler, "Authentication & SSO Handler", "OIDC/OAuth2", "Validates SSO and authentication against Corporate Active Directory.")
    Component(Routing_Configuration_Engine, "Routing & Configuration Engine", "Internal HTTPS/REST, Redis", "Fetches active routing rules from the Configuration & Feature Store, cached locally.")
    Component(Secrets_Management_Client, "Secrets Management Client", "Azure Managed Identity / HTTPS", "Retrieves certificates and OAuth secrets from Azure Key Vault.")
}

Rel(Azure_API_Management, Authentication_SSO_Handler, "Validates SSO and authentication", "OIDC/OAuth2")
Rel(Azure_API_Management, Routing_Configuration_Engine, "Fetches active routing rules", "Internal HTTPS/REST, cached locally")
Rel(Azure_API_Management, Secrets_Management_Client, "Retrieves certificates and OAuth secrets", "Azure Managed Identity / HTTPS")

@enduml

Adjuster Workspace.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Corporate Active Directory, "Corporate Active Directory", "Azure AD / Entra ID")
System_Ext(Claim Read Model Database, "Claim Read Model Database", "Azure Cosmos DB", "Delivers low-latency NoSQL reads to guarantee sub-2s screen loads")

Container_Boundary(Adjuster_Workspace, "Adjuster Workspace") {
    Component(Adjuster UI, "Adjuster UI", "React", "Provides the user interface for claims adjusters to review and manage claim data.")
    Component(Adjuster API Backend, "Adjuster API Backend", ".NET Core API", "Orchestrates adjuster workflows and validates Single Sign-On against Corporate Active Directory.")
}

Rel(Adjuster UI, Adjuster API Backend, "Routes adjuster traffic", "Internal HTTPS")
Rel(Adjuster API Backend, Corporate Active Directory, "Validates Single Sign-On", "OIDC / OAuth2 / TLS 1.3")
Rel(Adjuster API Backend, Claim Read Model Database, "Reads claim data", "TCP / Cosmos DB Direct Mode")
@enduml

Integration & Anti-Corruption Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Integration & Anti-Corruption Layer", "Integration & Anti-Corruption Layer") {
    Component("Translation Engine", "Translation Engine", ".NET Core / FluentValidation", "Validates and translates modern claims data formats into legacy-compatible payloads.")
    Component("Outbox Processor", "Outbox Processor", "MassTransit / Entity Framework Core / Azure SQL Serverless", "Implements the Transactional Outbox pattern to ensure reliable message delivery and prevent lost claims.")
    Component("Async Sync Worker", "Async Sync Worker", "MassTransit / Polly", "Handles asynchronous synchronization workflows with retry policies and resilience.")
    Component("Routing & Feature Router", "Routing & Feature Router", "Azure App Configuration", "Manages dynamic feature flags and routing for gradual claim-type migration and rollbacks.")
}

Rel("Translation Engine", "Outbox Processor", "Passes validated and translated payloads for reliable outbox persistence.")
Rel("Outbox Processor", "Async Sync Worker", "Dispatches asynchronous messages for synchronization.")
Rel("Routing & Feature Router", "Translation Engine", "Provides feature flags and routing rules to guide translation and processing.")

@enduml

Configuration & Feature Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Configuration & Feature Store container

Container_Boundary(config_feature_store, "Configuration & Feature Store") {
    Component(Configuration_SDK_Caching_Module, "Configuration SDK Caching Module", "Azure App Configuration SDK with native caching", "Provides sub-millisecond flag evaluations and local SDK caching with jittered polling.")
    Component(Managed_Identity_Authentication_Module, "Managed Identity Authentication Module", "Azure Managed Identities", "Handles secure authentication between services and the configuration store over HTTPS.")
}

Rel(Configuration_SDK_Caching_Module, Managed_Identity_Authentication_Module, "Authenticates requests using", "HTTPS")

@enduml
